namespace ArgentSea;
public sealed class InvalidShardArgumentsException : ApplicationException {
  InvalidShardArgumentsException();               // "An empty shard key type must have zeros for shard and record values."
  InvalidShardArgumentsException(string message);
  InvalidShardArgumentsException(string message, Exception innerException);
}
// Carries no properties beyond the message.
// Declared as part of the public surface for rejecting inconsistent ShardKey construction arguments (an 'empty' key whose shard or record values are not zero), but no code in the library currently throws it: the ShardKey family's constructors and parsers do not raise it, so callers will not observe it from ArgentSea itself. It remains available for application code that validates key arguments and wants a library-consistent exception type.
